def find_max(arr, n):
    if n == 1:
        return arr[0]
    mid = n // 2
    left_max = find_max(arr, mid)
    right_max = find_max(arr[mid:], n - mid)
    return max(left_max, right_max)

What is the time complexity of this ternary search?

def ternary_search(arr, lo, hi, target):
    if lo > hi:
        return -1
    t1 = lo + (hi - lo) // 3
    t2 = hi - (hi - lo) // 3
    if arr[t1] == target: return t1
    if arr[t2] == target: return t2
    if target < arr[t1]:
        return ternary_search(arr, lo, t1 - 1, target)
    elif target > arr[t2]:
        return ternary_search(arr, t2 + 1, hi, target)
    else:
        return ternary_search(arr, t1 + 1, t2 - 1, target)

