def stoogesort(arr, lo, hi):
    if arr[lo] > arr[hi]:
        arr[lo], arr[hi] = arr[hi], arr[lo]
    if hi - lo + 1 > 2:
        t = (hi - lo + 1) // 3
        stoogesort(arr, lo, hi - t)
        stoogesort(arr, lo + t, hi)
        stoogesort(arr, lo, hi - t)

