What is the time complexity of this function?

def max_subarray(arr, n, max_end):
    # Returns (max_ending_here, max_so_far)
    if n == 1:
        return arr[0], arr[0]
    prev_end, prev_max = max_subarray(arr, n - 1, max_end)
    curr_end = max(arr[n-1], prev_end + arr[n-1])
    return curr_end, max(prev_max, curr_end)

