def exponent_mod(base, exp, mod):
    if exp == 0:
        return 1
    if exp % 2 == 0:
        half = exponent_mod(base, exp // 2, mod)
        return (half * half) % mod
    return (base * exponent_mod(base, exp - 1, mod)) % mod

