What is the time complexity of this function?

def max_path_sum(grid, i, j):
    if i == len(grid) - 1 and j == len(grid[0]) - 1:
        return grid[i][j]
    if i == len(grid) - 1:
        return grid[i][j] + max_path_sum(grid, i, j + 1)
    if j == len(grid[0]) - 1:
        return grid[i][j] + max_path_sum(grid, i + 1, j)
    down = max_path_sum(grid, i + 1, j)
    right = max_path_sum(grid, i, j + 1)
    return grid[i][j] + max(down, right)
